import ast
from fractions import Fraction

# Translate the natural-language atomic statements into their truth values.
facts = {
    "The capital of Colombia is Bogota.": True,
    "The capital of Turkey is Ankara.": True,
    "The capital of Canada is Ottawa.": True,
    "The capital of Jordan is Beirut.": False,  # Jordan's capital is Amman.
    "The capital of Belarus is Minsk.": True,
    "The capital of Afghanistan is Kabul.": True,
    "The capital of Denmark is Copenhagen.": True,
    "The capital of Iran is Isfahan.": False,  # Iran's capital is Tehran.
    "The capital of Afghanistan is Kandahar.": False,
    "The capital of Nepal is Pokhara.": False,  # Nepal's capital is Kathmandu.
    "The capital of India is New Delhi.": True,
}

expressions = {
    "A": """not not not (not not (not ((True) or (-1 * 3 + -5 * 1 is greater than -10 * 7)) and (not (10 - (9 / 8) is greater than 4) or (10 - (10 / 1) > 2))) or not not not ((not (2 * -4 + 4 * -5 > 4 * 4) or (-1 * -2 + 4 * -10 > 4 * 1)) and (not not (4 - (8 / 1) <= -6) or not not not (max(1, 3, 1, 6) - min(1, 3, 1, 6) <= 7)))) and not not (not not (not not not ((max(-6, 5, -4, -4) - min(-6, 5, -4, -4) is greater than 2) or (The capital of Colombia is Bogota.)) and not not (not not (1 * 7 + -8 * -10 is greater than 3 * 4) or not not not (The capital of Turkey is Ankara.))) or not not not ((not not not (-10 - (10 / 2) is less than or equal to -1) and not not (False)) or ((-4 * -4 + -4 * 5 <= -8 * -1) or (False))))""",
    "B": """not (not (not (max(-1, -10, -5, -10) - min(-1, -10, -5, -10) <= 4) and (-9 * -1 > -10)) and (not (The capital of Canada is Ottawa.) or (-6 * -4 + 4 * 3 is greater than 3 * -7))) and (not (not (1 - (5 / 10) is less than or equal to 9) or (9 * -6 + -7 * 1 > 1 * -8)) or (not (-4 * 4 + -5 * 9 <= 6 * -10) or (max(7, -3, -10, -1) - min(7, -3, -10, -1) <= 6)))""",
    "C": """not ((not (not not (((not (not (not not (not not not (not (not not (not not not (4 * 9 > 6) and not not (The capital of Jordan is Beirut.)) or not not not (-3 * 7 is less than or equal to -6)) or (-9 * 4 + -3 * 2 <= 10 * 1)) and not not (1 * 4 + 2 * 1 is greater than 8 * -7)) or not not not (max(7, -4, -2, 1) - min(7, -4, -2, 1) is greater than 8)) and (2 * 2 <= -5)) and (6 * -8 > 3)) or (The capital of Belarus is Minsk.)) or (10 * 6 + 9 * 8 is greater than -2 * 10)) or not not not (-4 * 5 is less than or equal to -3)) or (max(-10, 1, -3, -4) - min(-10, 1, -3, -4) <= 8)) or (The capital of Afghanistan is Kabul.)) and (1 - (7 / -7) is greater than -10)""",
    "D": """not ((not (not (True) and (The capital of Colombia is Bogota.)) and (not not not (True) and not not (The capital of Afghanistan is Kabul.))) or (not (not (-8 * -7 + 5 * -10 is greater than 4 * -2) or (9 * 1 + -6 * -9 is less than or equal to -10 * 1)) and (not not (-8 * -7 + -8 * -1 is greater than -1 * 1) or not not not (The capital of Denmark is Copenhagen.)))) and (not not not (not not not (not not (The capital of Iran is Isfahan.) or not not not (The capital of Afghanistan is Kandahar.)) and not not (not (The capital of Afghanistan is Kabul.) or (5 - (-6 / 4) <= 6))) and not not (not (not not (True) or not not not (1 - (6 / -1) is greater than -6)) or (not not (-8 - (-3 / -6) > 3) or not not not (-4 * 1 + -5 * 3 is greater than -6 * 10))))""",
    "E": """not not not (not not ((not (not (not not (not (not (not not not (-1 - (-3 / -9) > 5) and not not (The capital of Nepal is Pokhara.)) or (-10 * -8 + 5 * -2 is less than or equal to -3 * 8)) or (5 * 3 + -9 * 9 <= 2 * -3)) or not not not (4 * -10 + -3 * 1 <= -9 * 1)) and (5 * -9 + -5 * 10 > -4 * -6)) and (True)) and (The capital of India is New Delhi.)) or not not not (max(-2, 4, -9, -8) - min(-2, 4, -9, -8) <= 7)) and not not (True)""",
}


def calculate(node):
    """Evaluate the expression AST with exact arithmetic and explicit logic."""
    if isinstance(node, ast.Expression):
        return calculate(node.body)
    if isinstance(node, ast.Constant):
        if type(node.value) in (bool, int):
            return node.value
        raise ValueError("Unsupported constant")
    if isinstance(node, ast.UnaryOp):
        value = calculate(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return +value
    if isinstance(node, ast.BinOp):
        left, right = calculate(node.left), calculate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return Fraction(left) / Fraction(right)
    if isinstance(node, ast.BoolOp):
        # Evaluate every operand, even when short-circuiting would suffice.
        values = [calculate(value) for value in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.Compare):
        values = [calculate(node.left)]
        values.extend(calculate(value) for value in node.comparators)
        results = []
        for left, op, right in zip(values, node.ops, values[1:]):
            if isinstance(op, ast.Gt):
                results.append(left > right)
            elif isinstance(op, ast.LtE):
                results.append(left <= right)
            else:
                raise ValueError("Unsupported comparison")
        return all(results)
    if isinstance(node, ast.Call):
        if (isinstance(node.func, ast.Name)
                and node.func.id in ("min", "max")
                and not node.keywords):
            args = [calculate(arg) for arg in node.args]
            return (min if node.func.id == "min" else max)(args)
    raise ValueError("Unsupported syntax: " + ast.dump(node))


def main():
    results = {}
    for label, text in expressions.items():
        for statement, truth in facts.items():
            text = text.replace(statement, str(truth))
        text = text.replace("is greater than", ">")
        text = text.replace("is less than or equal to", "<=")
        try:
            value = calculate(ast.parse(text, mode="eval"))
            if type(value) is not bool:
                raise ValueError("Expression did not produce a Boolean")
            results[label] = value
            print(f"{label} = {value}")
        except (SyntaxError, ValueError, ArithmeticError) as exc:
            print(f"{label}: UNSUPPORTED ({exc})")

    if len(results) != len(expressions):
        print("CHECK UNKNOWN")
        return

    true_options = [label for label, value in results.items() if value]
    print("True options:", ", ".join(true_options) or "none")
    submitted = "B"
    print("CHECK PASS" if true_options == [submitted] else "CHECK FAIL")


main()
